"""Add evaluators and their runs, and link scores to the run that wrote them.

Revision ID: 0505
Revises: 0504
Create Date: 2026-10-10

An evaluator scores traces automatically: a heuristic rule, an LLM judge called through the
gateway, or a customer's webhook. Each evaluation of one trace (or span) is an evaluator run.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application, so no column has a default.
* `evaluators` carries `project_id` and cascades from `projects`; `UNIQUE (project_id, name)`
  keeps names apart within a project. The name follows the score name rule (lower case, digits,
  `_`, `.`, `-`, at most 64 characters), because the evaluator's scores carry it. `kind` and
  `config.kind` always agree (CHECK), so a query can filter on the column without reading the
  JSON.
* `config` and `filters` are JSON validated by the API (a discriminated union); the database
  checks only that they are objects. `sampling_rate` is `numeric(5,4)` in `[0, 1]`.
* `monthly_budget_usd` is required for judges and must be positive (CHECK): a judge spends money
  unattended, so it never runs without a ceiling.
* `evaluator_runs` has no `project_id`: it belongs to its evaluator and cascades from it. Its
  row-level security policy asks whether the evaluator is visible, so a run is exactly as visible
  as its evaluator. The policy uses the same InitPlan form as the project policies.
* `cost_usd` and `reserved_usd` carry the judge's budget: a running run holds its estimated cost
  in `reserved_usd` until the call settles, so concurrent runs cannot both pass the budget.
  `heartbeat_at` lets the reaper fail a run whose worker died.
* `trace_id` and `span_id` are plain text, not foreign keys: traces are deleted by retention.
* `source` says why a run exists: `online` (the sampler picked the trace), `test` (a person
  pressed "Test" on the evaluator) or `experiment` (an experiment item was scored). Test and
  experiment evaluations are real runs so a judge's spend on them counts against the same monthly
  budget as sampled runs.
* A trace (or one of its spans) is sampled once per evaluator: the unique expression index treats
  a missing span as the empty string, because NULLs never collide in a plain unique index. It is
  partial (`WHERE source = 'online'`), so testing an evaluator on a trace, or an experiment that
  scores its own traces, never collides with the sampler.
* Indexes: `(evaluator_id, started_at DESC)` serves the runs listing and the month-to-date sums,
  `(trace_id)` the runs of a trace, the partial `(evaluator_id) WHERE status = 'running'` the
  reaper; `created_by` is indexed so deleting a user does not scan the table.
* `scores.evaluator_run_id` gains its foreign key (`ON DELETE SET NULL`: a score outlives the run
  that wrote it). The column and its partial index were created by 0502. The key is added
  `NOT VALID` and validated in a second statement, so the scan of `scores` does not hold the
  lock that blocks writes; every existing value is NULL, so validation cannot fail.

Downgrade drops the foreign key and the tables.
"""

from collections.abc import Sequence

from alembic import op

revision: str = "0505"
down_revision: str | None = "0504"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
RUN_EXPRESSION = "EXISTS (SELECT 1 FROM evaluators e WHERE e.id = evaluator_runs.evaluator_id)"
SCORES_FK = "scores_evaluator_run_id_fkey"


def upgrade() -> None:
    _create_tables()
    _enable_rls()
    _link_scores()


def _create_tables() -> None:
    op.execute(
        """
        CREATE TABLE evaluators (
            id                  uuid PRIMARY KEY,
            project_id          uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            name                text NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9_.-]{0,63}$'),
            kind                text NOT NULL CHECK (kind IN ('heuristic', 'llm_judge', 'webhook')),
            config              jsonb NOT NULL
                                CHECK (jsonb_typeof(config) = 'object' AND config->>'kind' = kind),
            sampling_rate       numeric(5, 4) NOT NULL DEFAULT 0
                                CHECK (sampling_rate BETWEEN 0 AND 1),
            filters             jsonb NOT NULL DEFAULT '{}'
                                CHECK (jsonb_typeof(filters) = 'object'),
            monthly_budget_usd  numeric(12, 4) CHECK (monthly_budget_usd > 0),
            enabled             boolean NOT NULL DEFAULT true,
            created_by          uuid REFERENCES users (id) ON DELETE SET NULL,
            created_at          timestamptz NOT NULL DEFAULT now(),
            updated_at          timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT evaluators_project_name_key UNIQUE (project_id, name),
            CONSTRAINT evaluators_judge_budget_check
                CHECK (kind <> 'llm_judge' OR monthly_budget_usd IS NOT NULL)
        )
        """
    )
    op.execute("CREATE INDEX evaluators_created_by_idx ON evaluators (created_by)")
    op.execute(
        """
        CREATE TABLE evaluator_runs (
            id            uuid PRIMARY KEY,
            evaluator_id  uuid NOT NULL REFERENCES evaluators (id) ON DELETE CASCADE,
            trace_id      text NOT NULL,
            span_id       text,
            status        text NOT NULL DEFAULT 'queued'
                          CHECK (status IN ('queued', 'running', 'done', 'failed')),
            source        text NOT NULL DEFAULT 'online'
                          CHECK (source IN ('online', 'test', 'experiment')),
            cost_usd      numeric(14, 8) NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
            reserved_usd  numeric(14, 8) NOT NULL DEFAULT 0 CHECK (reserved_usd >= 0),
            error         text CHECK (char_length(error) <= 500),
            started_at    timestamptz NOT NULL DEFAULT now(),
            heartbeat_at  timestamptz,
            finished_at   timestamptz
        )
        """
    )
    op.execute(
        "CREATE UNIQUE INDEX evaluator_runs_target_key "
        "ON evaluator_runs (evaluator_id, trace_id, coalesce(span_id, '')) "
        "WHERE source = 'online'"
    )
    op.execute(
        "CREATE INDEX evaluator_runs_evaluator_started_idx "
        "ON evaluator_runs (evaluator_id, started_at DESC)"
    )
    op.execute("CREATE INDEX evaluator_runs_trace_idx ON evaluator_runs (trace_id)")
    op.execute(
        "CREATE INDEX evaluator_runs_running_idx ON evaluator_runs (evaluator_id) "
        "WHERE status = 'running'"
    )


def _enable_rls() -> None:
    op.execute("ALTER TABLE evaluators ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE evaluators FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY evaluators_project_isolation ON evaluators "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY evaluators_worker_bypass ON evaluators "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )
    op.execute("ALTER TABLE evaluator_runs ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE evaluator_runs FORCE ROW LEVEL SECURITY")
    op.execute(
        "CREATE POLICY evaluator_runs_project_isolation ON evaluator_runs "
        f"USING ({RUN_EXPRESSION}) WITH CHECK ({RUN_EXPRESSION})"
    )
    op.execute(
        "CREATE POLICY evaluator_runs_worker_bypass ON evaluator_runs "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


def _link_scores() -> None:
    op.execute(
        f"ALTER TABLE scores ADD CONSTRAINT {SCORES_FK} FOREIGN KEY (evaluator_run_id) "
        "REFERENCES evaluator_runs (id) ON DELETE SET NULL NOT VALID"
    )
    op.execute(f"ALTER TABLE scores VALIDATE CONSTRAINT {SCORES_FK}")


def downgrade() -> None:
    op.execute(f"ALTER TABLE scores DROP CONSTRAINT IF EXISTS {SCORES_FK}")
    op.execute("DROP TABLE IF EXISTS evaluator_runs")
    op.execute("DROP TABLE IF EXISTS evaluators")
